package org.slavicmyths.quest185;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
/** Bounded per-player evidence, tutorial ownership and paid virtual-task receipts. */
public final class CleansingLessons extends SavedData {
 private record Sample(UUID owner,CompoundTag tag){}
 private static final Map<net.minecraft.server.MinecraftServer,CleansingLessons> LIVE=new WeakHashMap<>();private final Map<String,Sample> samplesByPosition=new HashMap<>();
 private final CompoundTag players=new CompoundTag();private final Set<String> work=new LinkedHashSet<>();
 public static CleansingLessons get(ServerLevel w){var d=w.getServer().overworld().getDataStorage().computeIfAbsent(new Factory<>(CleansingLessons::new,(n,r)->load(n)),"slavicmyths_cleansing_lessons185");LIVE.put(w.getServer(),d);return d;}
 private static String location(ServerLevel w,BlockPos pos){return w.dimension().location()+":"+pos.asLong();}
 public UUID tutorialOwner(ServerLevel w,BlockPos pos){var s=samplesByPosition.get(location(w,pos));return s==null?null:s.owner;}
 public static void naturalChange(ServerLevel w,BlockPos pos,BlockState state){var d=LIVE.get(w.getServer());if(d==null)return;var sample=d.samplesByPosition.get(location(w,pos));if(sample!=null){sample.tag.put("Expected",NbtUtils.writeBlockState(state));d.setDirty();}}
 public static void changed(ServerLevel w,BlockPos pos){var d=LIVE.get(w.getServer());if(d==null)return;var sample=d.samplesByPosition.remove(location(w,pos));if(sample!=null){sample.tag.putBoolean("Gone",true);d.setDirty();}}
 private CompoundTag player(UUID id){String key=id.toString();if(!players.contains(key,10))players.put(key,new CompoundTag());return players.getCompound(key);}
 public int count(UUID id){return Math.clamp(player(id).getInt("Count"),0,20);}
 public static boolean credit(CompoundTag n,String key){int count=Math.clamp(n.getInt("Count"),0,20);var seen=n.getCompound("Seen");if(count>=20||seen.contains(key))return false;seen.putBoolean(key,true);n.put("Seen",seen);n.putInt("Count",count+1);return true;}
 public void restored(ServerLevel w,BlockPos pos,UUID actor,UUID tutorialOwner){if(tutorialOwner!=null&&!tutorialOwner.equals(actor))return;var n=player(actor);if(credit(n,location(w,pos))){setDirty();notify(w,actor);}}
 private void notify(ServerLevel w,UUID id){var p=w.getServer().getPlayerList().getPlayer(id);if(p!=null){Quest185Story.data(p).putInt("RestoreEarthCleaned",count(id));p.displayClientMessage(Quest185Story.text("earth_progress",count(id)),true);}}
 public boolean begin(ServerPlayer p){var n=player(p.getUUID());if(count(p.getUUID())>=20)return false;if(n.hasUUID("Tutorial")){refresh(p);return true;}n.putUUID("Tutorial",UUID.randomUUID());n.putBoolean("Virtual",true);setDirty();var door=Quest185Sessions.door(p);var w=p.serverLevel();if(door==null||!w.hasChunkAt(door))return true;long active=players.getAllKeys().stream().map(players::getCompound).filter(a->!a.getList("Samples",10).isEmpty()&&!a.getBoolean("Finished")).count();if(active>=32)return true;
  // One 4x5 natural turf patch, off the entrance and paths; never load chunks for it.
  for(int radius:new int[]{12,16,20})for(var dir:new Direction[]{Direction.WEST,Direction.EAST,Direction.SOUTH,Direction.NORTH})for(int dy:new int[]{-1,-2,0,-3,1}){var center=door.relative(dir,radius).offset(0,dy,0);var positions=new ArrayList<BlockPos>();boolean valid=true;for(int x=0;x<4&&valid;x++)for(int z=0;z<5;z++){var at=center.offset(x,0,z);if(at.distSqr(door)<100||at.distSqr(door)>576||occupied(w,at)||!natural(p,at)){valid=false;break;}positions.add(at);}if(!valid||positions.size()!=20)continue;var samples=new ListTag();for(var at:positions){var origin=w.getBlockState(at);var sample=new CompoundTag();sample.putLong("Pos",at.asLong());sample.putString("Dimension",w.dimension().location().toString());sample.put("Original",NbtUtils.writeBlockState(origin));var expected=org.slavicmyths.mor.MorBlocks.copy(origin,org.slavicmyths.mor.MorBlocks.BLOCKS.get(origin.is(Blocks.GRASS_BLOCK)?"grass_block":"dirt").get().defaultBlockState());sample.put("Expected",NbtUtils.writeBlockState(expected));samples.add(sample);}n.put("Samples",samples);setDirty();for(var raw:samples){var sample=(CompoundTag)raw;var at=BlockPos.of(sample.getLong("Pos"));if(org.slavicmyths.mor.MorBlocks.convert(w,at,p)!=org.slavicmyths.mor.MorBlocks.Result.CONVERTED){rollback(w,n);return true;}sample.putBoolean("Live",true);samplesByPosition.put(location(w,at),new Sample(p.getUUID(),sample));}n.putBoolean("Virtual",false);setDirty();p.displayClientMessage(Quest185Story.text("earth_patch",center.getX(),center.getY(),center.getZ()),false);return true;}
  return true;
 }
 private boolean occupied(ServerLevel w,BlockPos pos){return samplesByPosition.containsKey(location(w,pos));}
 private boolean natural(ServerPlayer p,BlockPos pos){var w=p.serverLevel();for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){var at=pos.offset(dx,0,dz);if(!w.hasChunkAt(at)||!w.getBlockState(at).is(Blocks.GRASS_BLOCK)&&!w.getBlockState(at).is(Blocks.DIRT)||!w.isEmptyBlock(at.above())||!w.isEmptyBlock(at.above(2))||w.getBlockEntity(at)!=null||!w.getFluidState(at).isEmpty()||CleansedLand.protectedAt(w,at)||!CleansingTasks.permitted(p,at,w.getBlockState(at)))return false;}return true;}
 public void refresh(ServerPlayer p){var n=player(p.getUUID());boolean lost=false;for(var raw:n.getList("Samples",10)){var s=(CompoundTag)raw;if(s.getBoolean("Gone"))lost=true;else if(s.getString("Dimension").equals(p.serverLevel().dimension().location().toString())){var at=BlockPos.of(s.getLong("Pos"));if(p.serverLevel().hasChunkAt(at)&&org.slavicmyths.mor.MorBlocks.index(p.serverLevel().getBlockState(at))<0)lost=true;}}if(lost&&count(p.getUUID())<20){n.putBoolean("Virtual",true);rollback(p.serverLevel(),n);setDirty();}}
 public void debugCount(UUID owner,int count){var n=player(owner);n.putInt("Count",Math.clamp(count,0,20));setDirty();}
 public void reset(ServerPlayer p){var n=player(p.getUUID());n.putInt("Count",0);n.put("Seen",new CompoundTag());n.remove("VirtualDue");n.putBoolean("Finished",true);rollback(p.serverLevel(),n);setDirty();}
 public boolean virtual(UUID owner){return player(owner).getBoolean("Virtual");}
 public boolean startVirtual(ServerPlayer p){var n=player(p.getUUID());if(work.size()>=8||!n.getBoolean("Virtual")||n.contains("VirtualDue")||count(p.getUUID())>=20||p.isSpectator())return false;if(!p.isCreative()&&!Quest185Story.spend(p,Quest185Content.POWDER.get(),1))return false;work.add(p.getUUID().toString());n.putLong("VirtualDue",p.server.overworld().getGameTime()+60);n.putInt("VirtualSize",Math.min(9,20-count(p.getUUID())));n.putUUID("Receipt",UUID.randomUUID());setDirty();Quest185Content.sound(p,"purify");return true;}
 public void finish(ServerPlayer p){var n=player(p.getUUID());n.putBoolean("Finished",true);n.remove("VirtualDue");setDirty();rollback(p.serverLevel(),n);}
 private void rollback(ServerLevel w,CompoundTag n){for(var raw:n.getList("Samples",10)){var s=(CompoundTag)raw;if(s.getBoolean("Gone")||!s.getString("Dimension").equals(w.dimension().location().toString()))continue;var pos=BlockPos.of(s.getLong("Pos"));if(!w.hasChunkAt(pos))continue;var lookup=w.holderLookup(net.minecraft.core.registries.Registries.BLOCK);var expected=NbtUtils.readBlockState(lookup,s.getCompound("Expected"));if(samplesByPosition.containsKey(location(w,pos))&&w.getBlockState(pos).equals(expected)){var original=NbtUtils.readBlockState(lookup,s.getCompound("Original"));if(!original.isAir())w.setBlock(pos,original,3);}samplesByPosition.remove(location(w,pos));s.putBoolean("Gone",true);}if(n.getList("Samples",10).stream().anyMatch(raw->!((CompoundTag)raw).getBoolean("Gone")))for(var key:players.getAllKeys())if(players.getCompound(key)==n)work.add(key);setDirty();}
 public void tick(ServerLevel overworld){long now=overworld.getGameTime();if(work.isEmpty())return;int budget=8;for(var key:List.copyOf(work)){if(budget--<=0)break;var n=players.getCompound(key);if(n.contains("VirtualDue")&&now>=n.getLong("VirtualDue")){int size=Math.clamp(n.getInt("VirtualSize"),0,9);String receipt=n.getUUID("Receipt").toString();for(int i=0;i<size;i++)credit(n,"lesson:"+receipt+":"+i);n.remove("VirtualDue");n.remove("VirtualSize");setDirty();notify(overworld,UUID.fromString(key));}if((n.getBoolean("Finished")||n.getBoolean("Virtual"))&&now%20==0)for(var raw:n.getList("Samples",10)){var sample=(CompoundTag)raw;if(sample.getBoolean("Gone"))continue;var level=overworld.getServer().getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(sample.getString("Dimension"))));if(level!=null)rollback(level,n);}if(!n.contains("VirtualDue")&&n.getList("Samples",10).stream().allMatch(raw->((CompoundTag)raw).getBoolean("Gone")))work.remove(key);else{work.remove(key);work.add(key);}}}
 @Override public CompoundTag save(CompoundTag n,HolderLookup.Provider r){n.put("Players",players.copy());return n;}
 public static CleansingLessons load(CompoundTag n){var d=new CleansingLessons();d.players.merge(n.getCompound("Players"));for(var key:d.players.getAllKeys()){var p=d.players.getCompound(key);for(var raw:p.getList("Samples",10)){var sample=(CompoundTag)raw;if(!sample.getBoolean("Gone")&&sample.getBoolean("Live"))d.samplesByPosition.put(sample.getString("Dimension")+":"+sample.getLong("Pos"),new Sample(UUID.fromString(key),sample));}if(p.contains("VirtualDue")||(p.getBoolean("Finished")||p.getBoolean("Virtual"))&&!p.getList("Samples",10).isEmpty())d.work.add(key);}return d;}
 private CleansingLessons(){}
}
